    // Returns whether it wrote, so the caller knows to arm regeneration afterwards
    bool OnModifierChange(RE::Actor* a_actor, MOD a_mod, RE::ActorValue a_av, float a_delta)
    {
        if (!a_actor) {
            return false;
        }

        LogState(a_actor, a_mod, a_av, a_delta);

        if (g_mode.load() == Fortify::Mode::kOff) {
            // Still watched while off, read only, so leaving Off does not start from a stale penalty
            if (a_mod == MOD::kPermanent) {
                static_cast<void>(SurvivalPenalty(a_actor, a_mod, a_av, a_delta));
            }
            return false;
        }

        auto* slots = SlotsFor(a_actor, a_av);
        if (!slots) {
            return false;
        }

        const auto previous = std::exchange(t_lastDamage, {});
        if (a_mod == MOD::kDamage) {
            t_lastDamage = { a_actor, a_av, a_delta };
            return false;
        }
        if (a_mod != MOD::kPermanent && a_mod != MOD::kTemporary) {
            return false;
        }
        if (g_playerOnly.load() && !a_actor->IsPlayerRef()) {
            return false;
        }

        const float before = slots->modifiers[a_mod];
        const auto penalty = SurvivalPenalty(a_actor, a_mod, a_av, a_delta);
        const float rise = FortifyPart(before + penalty.before, before + a_delta + penalty.after);

        ++g_seen;
        if (std::abs(rise) < 0.001f) {
            ++g_restores;
            return false;
        }

        // A damage change of the same size right before a rise means the caller manages current, so correcting it again takes the rise twice (colinswrath/Survival-Mode-Improved-SKSE/include/AvPenaltyManager.h:277-282)
        if (rise > 0.0f && previous.actor == a_actor && previous.av == a_av && std::abs(std::abs(previous.delta) - std::abs(a_delta)) < 0.001f) {
            ++g_precompensated;
            return false;
        }

        if (rise > 0.0f && penalty.fortified) {
            penalty.fortified->store(true);
        }

        auto* owner = a_actor->AsActorValueOwner();
        const float damage = slots->modifiers[MOD::kDamage];
        const float maxBefore = owner->GetBaseActorValue(a_av) + slots->modifiers[MOD::kPermanent] +
                                slots->modifiers[MOD::kTemporary];

        const Snapshot before_{ slots->modifiers[MOD::kPermanent], slots->modifiers[MOD::kTemporary], damage,
                                maxBefore + damage };
        const float wanted = WantedDamage(before_, maxBefore + rise);

        if (a_av == RE::ActorValue::kHealth && before_.current > 0.0f && before_.current + a_delta <= 0.0f) {
            ++g_deaths;
            logger::info("{}: max {:.1f} -> {:.1f}, current {:.1f} held, vanilla would give {:.1f}. Death prevented.",
                         Util::Who(a_actor), maxBefore, maxBefore + a_delta, before_.current,
                         before_.current + a_delta);
        }

        if (std::abs(wanted - damage) < 0.001f) {
            return false;
        }

        // Raw rather than through ModActorValue, which would re-enter the function this hook sits inside
        slots->modifiers[MOD::kDamage] = wanted;
        InvalidateCached(a_actor, a_av);
        ++g_corrected;

        if (spdlog::should_log(spdlog::level::debug)) {
            logger::debug("{} av {}: {} {:.1f} -> {:.1f}, fortify part {:.1f}, damage {:.1f} -> {:.1f}",
                          Util::Who(a_actor), static_cast<int>(a_av),
                          a_mod == MOD::kPermanent ? "perm" : "temp", before, before + a_delta, rise, damage,
                          wanted);
        }

        return true;
    }

    template <std::size_t Index>
    struct ModifierCallHook
    {
        static void thunk(RE::Actor* a_actor, MOD a_mod, RE::ActorValue a_av, float a_delta, RE::Actor* a_source)
        {
#ifdef FF_DEBUG_PANEL
            ++g_siteHits[Index];
            if (a_actor && (a_mod == MOD::kPermanent || a_mod == MOD::kTemporary) && SlotsFor(a_actor, a_av)) {
                RecordCaller(Index, a_actor, a_mod, a_av, a_delta);
            }
#endif
            const bool wrote = OnModifierChange(a_actor, a_mod, a_av, a_delta);
            func(a_actor, a_mod, a_av, a_delta, a_source);

            // A raw write buys the number without the engine's bookkeeping, so regeneration is never armed. The round trip nets to zero while making two real calls
            // After the original, because ModActorValue re-enters the function this hook sits inside
            if (wrote && a_actor) {
                auto* owner = a_actor->AsActorValueOwner();
                owner->ModActorValue(MOD::kDamage, a_av, ARM_NUDGE);
                owner->ModActorValue(MOD::kDamage, a_av, -ARM_NUDGE);
                t_lastDamage = {};
            }
        }

        static inline REL::Relocation<decltype(thunk)> func;
    };

#ifdef FF_DEBUG_PANEL
    std::atomic_int32_t g_snapsRemaining{ 0 };
    std::chrono::steady_clock::time_point g_lastSnap{};

    // Time sampled as well as event driven, so a cause that stops the function being called still leaves evidence
    struct SnapshotTickHook
    {
        static void thunk()
        {
            func();

            if (g_snapsRemaining <= 0) {
                return;
            }
            if (auto* ui = RE::UI::GetSingleton(); !ui || ui->GameIsPaused()) {
                return;
            }

            const auto now = std::chrono::steady_clock::now();
            if (std::chrono::duration<float>(now - g_lastSnap).count() < 0.5f) {
                return;
            }
            g_lastSnap = now;
            --g_snapsRemaining;
            LogSnapshot("tick");
        }

        static inline REL::Relocation<decltype(thunk)> func;
    };
#endif

